function VR_Random (Cmd: char; NumParams: integer; ErmCmd: PErmCmd; SubCmd: PErmSubCmd): integer;
var
  VarParam: PErmCmdParam;
  ValType:  integer;

begin
  result   := 1;
  VarParam := @ErmCmd.Params[0];

  if not(VarParam.GetType() in PARAM_VARTYPES_INTS) then begin
    ShowErmError('"!!VR" - random functions can operate on integers only');
    result := 0; exit;
  end;

  case Cmd of
    'R': begin
      if NumParams >= 4 then begin
        result := ord(SetErmParamValue(VarParam, Tweaks.RandomRangeWithFreeParam(SubCmd.Nums[1], SubCmd.Nums[2], SubCmd.Nums[3])));
      end else if NumParams >= 3 then begin
        result := ord(SetErmParamValue(VarParam, Heroes.RandomRange(SubCmd.Nums[1], SubCmd.Nums[2])));
      end else if NumParams >= 2 then begin
        Heroes.SRand(SubCmd.Nums[1]);
      end else begin
        result := ord(SetErmParamValue(VarParam, GetErmParamValue(VarParam, ValType) + Heroes.RandomRange(0, SubCmd.Nums[0])));
      end;
    end;

    'T': begin
      if NumParams >= 3 then begin
        result := ord(SetErmParamValue(VarParam, FastRand.Rng.RandomRange(SubCmd.Nums[1], SubCmd.Nums[2])));
      end else if NumParams >= 2 then begin
        ShowErmError('"!!VR:T" - it''s forbidden to seed the unique generator');
        result := 0; exit;
      end else begin
        result := ord(SetErmParamValue(VarParam, GetErmParamValue(VarParam, ValType) + FastRand.Rng.RandomRange(0, SubCmd.Nums[0])));
      end;
    end;
  else
    ShowErmError('"!!VR" - impossible case in random operation');
    result := 0; exit;
  end; // .switch Cmd
end; // .function VR_Random

function RandomRange (Min, Max: integer): integer;
begin
  result := ApiJack.CallFast(Ptr($50C7C0), Min, Max);
end;

procedure SRand (Seed: integer);
begin
  ApiJack.CallThis(Ptr($50C7B0), Seed);
end;

function _RandomRangeWithFreeParam (CallerAddr: pointer; MinValue, MaxValue, FreeParam: integer): integer;
begin
  CombatRngFreeParam := FreeParam;
  result             := GlobalRng.RandomRange(MinValue, MaxValue);
  DebugRandomRange(CallerAddr, MinValue, MaxValue, result);
  CombatRngFreeParam := 0;
end;

CLangRng               := FastRand.TClangRng.Create(FastRand.MakeSecureSeedWithFallback);
QualitativeRng         := FastRand.TXoroshiro128Rng.Create(FastRand.MakeSecureSeedWithFallback);
BattleDeterministicRng := TBattleDeterministicRng.Create(@CombatId, @CombatRound, @CombatActionId, @CombatRngFreeParam);
GlobalRng              := QualitativeRng;

function RandomRange (Rng: TRng; MinValue, MaxValue: integer): integer;
const
  MAX_UNBIAS_ATTEMPTS = 100;

var
  RangeLen:         cardinal;
  BiasedRangeLen:   cardinal;
  MaxUnbiasedValue: cardinal;
  i:                integer;

begin
  {!} Assert(Rng <> nil);

  if MinValue >= MaxValue then begin
    result := MinValue;
    exit;
  end;

  result := Rng.Random;

  if (MinValue > Low(integer)) or (MaxValue < High(integer)) then begin
    i                := 2;
    RangeLen         := cardinal(MaxValue - MinValue) + 1;
    BiasedRangeLen   := High(cardinal) mod RangeLen + 1;

    if BiasedRangeLen = RangeLen then begin
      BiasedRangeLen := 0;
    end;

    MaxUnbiasedValue := High(cardinal) - BiasedRangeLen;

    while (cardinal(result) > MaxUnbiasedValue) and (i <= MAX_UNBIAS_ATTEMPTS) do begin
      result := Rng.Random;
      Inc(i);
    end;

    result := MinValue + integer(cardinal(result) mod RangeLen);
  end;
end;
